/**
 * Button component with multiple variants, sizes, and loading states.
 *
 * @example
 * ```tsx
 * <Button variant="primary" size="md">
 *   Save
 * </Button>
 *
 * <Button variant="outline" isLoading>
 *   Submitting...
 * </Button>
 * ```
 */
export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      children,
      variant = 'primary',
      size = 'md',
      isLoading = false,
      leftIcon,
      rightIcon,
      fullWidth = false,
      className = '',
      disabled,
      type = 'button',
      ...props
    },
    ref
  ) => {
    const isDisabled = disabled || isLoading

    return (
      <button
        ref={ref}
        type={type}
        disabled={isDisabled}
        className={`
          inline-flex items-center justify-center
          font-medium rounded-lg
          transition-colors duration-150
          focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2
          disabled:opacity-50 disabled:cursor-not-allowed
          ${variantStyles[variant]}
          ${sizeStyles[size]}
          ${fullWidth ? 'w-full' : ''}
          ${className}
        `.trim().replace(/\s+/g, ' ')}
        aria-busy={isLoading}
        {...props}
      >
        {isLoading && (
          <Spinner
            className={size === 'sm' ? 'h-3.5 w-3.5' : size === 'lg' ? 'h-5 w-5' : 'h-4 w-4'}
          />
        )}
        {!isLoading && leftIcon && <span className="shrink-0">{leftIcon}</span>}
        {children}
        {!isLoading && rightIcon && <span className="shrink-0">{rightIcon}</span>}
      </button>
    )
  }
)

Button.displayName = 'Button'

export default Button

import { forwardRef, type HTMLAttributes, type ReactNode } from 'react'

export interface CardProps extends HTMLAttributes<HTMLDivElement> {
  /** Card padding size */
  padding?: 'none' | 'sm' | 'md' | 'lg'
  /** Whether to show border */
  bordered?: boolean
  /** Whether to show shadow */
  shadow?: 'none' | 'sm' | 'md' | 'lg'
  /** Whether card is clickable/interactive */
  interactive?: boolean
}

export interface CardHeaderProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  /** Card title */
  title?: ReactNode
  /** Card subtitle or description */
  subtitle?: ReactNode
  /** Action element (button, menu, etc.) */
  action?: ReactNode
}

export interface CardFooterProps extends HTMLAttributes<HTMLDivElement> {
  /** Align footer content */
  align?: 'left' | 'center' | 'right' | 'between'
}

const paddingStyles = {
  none: '',
  sm: 'p-3',
  md: 'p-4',
  lg: 'p-6',
}

const shadowStyles = {
  none: '',
  sm: 'shadow-sm',
  md: 'shadow-md',
  lg: 'shadow-lg',
}

const alignStyles = {
  left: 'justify-start',
  center: 'justify-center',
  right: 'justify-end',
  between: 'justify-between',
}

/**
 * Card component for grouping related content.
 *
 * @example
 * ```tsx
 * <Card>
 *   <CardHeader title="Urun Bilgileri" subtitle="Urun detaylarini duzenleyin" />
 *   <CardContent>
 *     <p>Icerik burada...</p>
 *   </CardContent>
 *   <CardFooter>
 *     <Button>Kaydet</Button>
 *   </CardFooter>
 * </Card>
 * ```
 */
export const Card = forwardRef<HTMLDivElement, CardProps>(
  (
    {
      children,
      padding = 'none',
      bordered = true,
      shadow = 'sm',
      interactive = false,
      className = '',
      ...props
    },
    ref
  ) => {
    return (
      <div
        ref={ref}
        className={`
          bg-white dark:bg-secondary-800
          rounded-xl overflow-hidden
          ${bordered ? 'border border-secondary-200 dark:border-secondary-700' : ''}
          ${shadowStyles[shadow]}
          ${paddingStyles[padding]}
          ${interactive ? 'transition-shadow duration-150 hover:shadow-md cursor-pointer' : ''}
          ${className}
        `.trim().replace(/\s+/g, ' ')}
        {...props}
      >
        {children}
      </div>
    )
  }
)

Card.displayName = 'Card'

/**
